#[napi(object)]
pub struct NativeStackEntry {
    pub basis: Option<u32>,
    pub grow: Option<u32>,
    pub shrink: Option<u32>,
    pub min_size: Option<u32>,
    pub max_size: Option<u32>,
}

#[napi(js_name = "nativeAllocateStackSizes")]
pub fn native_allocate_stack_sizes(
    entries: Vec<NativeStackEntry>,
    intrinsic_sizes: Vec<u32>,
    available_size: Option<u32>,
    gap: u32,
) -> Vec<u32> {
    let entries: Vec<StackEntry> = entries
        .into_iter()
        .map(|entry| StackEntry {
            basis: entry.basis.map(|value| value as usize),
            grow: entry.grow.unwrap_or(0) as usize,
            shrink: entry.shrink.unwrap_or(1) as usize,
            min_size: entry.min_size.unwrap_or(0) as usize,
            max_size: entry.max_size.map_or(usize::MAX, |value| value as usize),
            visible: None,
        })
        .collect();
    let intrinsic_sizes: Vec<usize> = intrinsic_sizes
        .into_iter()
        .map(|value| value as usize)
        .collect();
    allocate_stack_sizes(
        &entries,
        &intrinsic_sizes,
        available_size.map(|value| value as usize),
        gap as usize,
    )
    .into_iter()
    .map(|value| value.min(u32::MAX as usize) as u32)
    .collect()
}

