fn native_stdin_events(events: Vec<StdinEvent>) -> Vec<NativeStdinEvent> {
    events
        .into_iter()
        .map(|event| match event {
            StdinEvent::Data(value) => NativeStdinEvent {
                kind: "data".to_owned(),
                value,
            },
            StdinEvent::Paste(value) => NativeStdinEvent {
                kind: "paste".to_owned(),
                value,
            },
        })
        .collect()
}

