#[napi]
pub struct NativeInputState {
    inner: Input,
    submitted: std::sync::Arc<std::sync::Mutex<Option<String>>>,
    escaped: std::sync::Arc<std::sync::atomic::AtomicBool>,
}

#[napi]
impl NativeInputState {
    #[napi(constructor)]
    pub fn new() -> Self {
        let submitted = std::sync::Arc::new(std::sync::Mutex::new(None));
        let escaped = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let mut inner = Input::new();
        let submit_slot = submitted.clone();
        inner.set_on_submit(Some(Box::new(move |value| {
            *submit_slot.lock().expect("input submit slot poisoned") = Some(value);
        })));
        let escape_slot = escaped.clone();
        inner.set_on_escape(Some(Box::new(move || {
            escape_slot.store(true, std::sync::atomic::Ordering::SeqCst);
        })));
        Self {
            inner,
            submitted,
            escaped,
        }
    }

    #[napi(getter)]
    pub fn focused(&self) -> bool {
        self.inner.focused
    }

    #[napi(setter)]
    pub fn set_focused(&mut self, focused: bool) {
        self.inner.focused = focused;
    }

    #[napi]
    pub fn get_value(&self) -> String {
        self.inner.get_value().to_owned()
    }

    #[napi]
    pub fn set_value(&mut self, value: String) {
        self.inner.set_value(value);
    }

    #[napi]
    pub fn handle_input(&mut self, data: String) -> NativeInputEvents {
        self.inner.handle_input(&data);
        NativeInputEvents {
            submit: self
                .submitted
                .lock()
                .expect("input submit slot poisoned")
                .take(),
            escape: self
                .escaped
                .swap(false, std::sync::atomic::Ordering::SeqCst),
        }
    }

    #[napi]
    pub fn invalidate(&mut self) {
        self.inner.invalidate();
    }

    #[napi]
    pub fn render(&mut self, width: u32) -> Vec<String> {
        self.inner.render(width as usize)
    }
}

impl Default for NativeInputState {
    fn default() -> Self {
        Self::new()
    }
}

