#[napi]
pub struct NativeEditorState {
    inner: Editor,
    submitted: std::sync::Arc<std::sync::Mutex<Option<String>>>,
    changed: std::sync::Arc<std::sync::Mutex<Option<String>>>,
}

#[napi]
impl NativeEditorState {
    #[napi(constructor)]
    pub fn new(padding_x: u32, autocomplete_max_visible: Option<u32>) -> Self {
        let submitted = std::sync::Arc::new(std::sync::Mutex::new(None));
        let changed = std::sync::Arc::new(std::sync::Mutex::new(None));
        let mut inner = Editor::new(
            Box::new(DetachedEditorHost::default()),
            EditorTheme::plain(),
            EditorOptions {
                padding_x: padding_x as usize,
                autocomplete_max_visible: autocomplete_max_visible.map(|value| value as usize),
                word_segmenter: None,
            },
        );
        let submit_slot = submitted.clone();
        inner.set_on_submit(Some(Box::new(move |value| {
            *submit_slot.lock().expect("editor submit slot poisoned") = Some(value);
        })));
        let change_slot = changed.clone();
        inner.set_on_change(Some(Box::new(move |value| {
            *change_slot.lock().expect("editor change slot poisoned") = Some(value);
        })));
        Self {
            inner,
            submitted,
            changed,
        }
    }

    #[napi(getter)]
    pub fn focused(&self) -> bool {
        self.inner.focused
    }

    #[napi(setter)]
    pub fn set_focused(&mut self, focused: bool) {
        self.inner.focused = focused;
    }

    #[napi(getter)]
    pub fn disable_submit(&self) -> bool {
        self.inner.disable_submit
    }

    #[napi(setter)]
    pub fn set_disable_submit(&mut self, disable: bool) {
        self.inner.disable_submit = disable;
    }

    #[napi]
    pub fn get_padding_x(&self) -> u32 {
        self.inner.get_padding_x().min(u32::MAX as usize) as u32
    }

    #[napi]
    pub fn set_padding_x(&mut self, padding: u32) {
        self.inner.set_padding_x(padding as usize);
    }

    #[napi]
    pub fn get_autocomplete_max_visible(&self) -> u32 {
        self.inner
            .get_autocomplete_max_visible()
            .min(u32::MAX as usize) as u32
    }

    #[napi]
    pub fn set_autocomplete_max_visible(&mut self, max_visible: u32) {
        self.inner
            .set_autocomplete_max_visible(max_visible as usize);
    }

    #[napi]
    pub fn add_to_history(&mut self, text: String) {
        self.inner.add_to_history(text);
    }

    #[napi]
    pub fn get_text(&self) -> String {
        self.inner.get_text()
    }

    #[napi]
    pub fn get_expanded_text(&self) -> String {
        self.inner.get_expanded_text()
    }

    #[napi]
    pub fn get_lines(&self) -> Vec<String> {
        self.inner.get_lines()
    }

    #[napi]
    pub fn get_cursor(&self) -> NativeEditorCursor {
        let cursor = self.inner.get_cursor();
        NativeEditorCursor {
            line: cursor.line.min(u32::MAX as usize) as u32,
            col: cursor.col.min(u32::MAX as usize) as u32,
        }
    }

    #[napi]
    pub fn set_text(&mut self, text: String) -> NativeEditorEvents {
        self.inner.set_text(text);
        self.take_events()
    }

    #[napi]
    pub fn insert_text_at_cursor(&mut self, text: String) -> NativeEditorEvents {
        self.inner.insert_text_at_cursor(text);
        self.take_events()
    }

    #[napi]
    pub fn handle_input(&mut self, data: String) -> NativeEditorEvents {
        self.inner.handle_input(&data);
        self.take_events()
    }

    #[napi]
    pub fn is_showing_autocomplete(&self) -> bool {
        self.inner.is_showing_autocomplete()
    }

    #[napi]
    pub fn invalidate(&mut self) {
        self.inner.invalidate();
    }

    #[napi]
    pub fn render(&mut self, width: u32) -> Vec<String> {
        self.inner.render(width as usize)
    }
}

impl NativeEditorState {
    fn take_events(&self) -> NativeEditorEvents {
        NativeEditorEvents {
            submit: self
                .submitted
                .lock()
                .expect("editor submit slot poisoned")
                .take(),
            change: self
                .changed
                .lock()
                .expect("editor change slot poisoned")
                .take(),
        }
    }
}

fn plain_markdown_theme() -> MarkdownTheme {
    fn style() -> pie_components::StyleFn {
        Box::new(str::to_owned)
    }
    MarkdownTheme {
        heading: style(),
        link: style(),
        link_url: style(),
        code: style(),
        code_block: style(),
        code_block_border: style(),
        quote: style(),
        quote_border: style(),
        hr: style(),
        list_bullet: style(),
        bold: style(),
        italic: style(),
        strikethrough: style(),
        underline: style(),
        highlight_code: None,
        code_block_indent: None,
    }
}

