fn push_utf16(output: &mut Vec<u16>, value: &str) {
    output.extend(value.encode_utf16());
}

fn js_is_whitespace_unit(unit: u16) -> bool {
    matches!(
        unit,
        0x0009..=0x000d
            | 0x0020
            | 0x00a0
            | 0x1680
            | 0x2000..=0x200a
            | 0x2028
            | 0x2029
            | 0x202f
            | 0x205f
            | 0x3000
            | 0xfeff
    )
}

fn fuzzy_match_query(query: &[u16], text: &[u16]) -> NativeFuzzyResult {
    if query.is_empty() {
        return NativeFuzzyResult {
            matches: true,
            score: 0.0,
        };
    }
    if query.len() > text.len() {
        return NativeFuzzyResult {
            matches: false,
            score: 0.0,
        };
    }

    let mut query_index = 0usize;
    let mut score = 0.0f64;
    let mut last_match_index = -1isize;
    let mut consecutive_matches = 0i64;
    for (index, unit) in text.iter().copied().enumerate() {
        if query_index >= query.len() {
            break;
        }
        if unit != query[query_index] {
            continue;
        }
        let is_word_boundary = index == 0
            || js_is_whitespace_unit(text[index - 1])
            || matches!(text[index - 1], 0x002d | 0x005f | 0x002e | 0x002f | 0x003a);
        if last_match_index == index as isize - 1 {
            consecutive_matches += 1;
            score -= (consecutive_matches * 5) as f64;
        } else {
            consecutive_matches = 0;
            if last_match_index >= 0 {
                score += (index as isize - last_match_index - 1) as f64 * 2.0;
            }
        }
        if is_word_boundary {
            score -= 10.0;
        }
        score += index as f64 * 0.1;
        last_match_index = index as isize;
        query_index += 1;
    }
    if query_index < query.len() {
        return NativeFuzzyResult {
            matches: false,
            score: 0.0,
        };
    }
    if query == text {
        score -= 100.0;
    }
    NativeFuzzyResult {
        matches: true,
        score,
    }
}

fn swapped_ascii_query(query: &[u16]) -> Option<Vec<u16>> {
    let is_digit = |unit: u16| (u16::from(b'0')..=u16::from(b'9')).contains(&unit);
    let is_letter = |unit: u16| (u16::from(b'a')..=u16::from(b'z')).contains(&unit);
    if !query
        .first()
        .copied()
        .is_some_and(|unit| is_digit(unit) || is_letter(unit))
    {
        return None;
    }
    let letters_then_digits = {
        let letters_end = query
            .iter()
            .position(|unit| is_digit(*unit))
            .unwrap_or(query.len());
        letters_end > 0
            && letters_end < query.len()
            && query[..letters_end].iter().all(|unit| is_letter(*unit))
            && query[letters_end..].iter().all(|unit| is_digit(*unit))
    };
    let digits_then_letters = {
        let digits_end = query
            .iter()
            .position(|unit| !is_digit(*unit))
            .unwrap_or(query.len());
        digits_end > 0
            && digits_end < query.len()
            && query[..digits_end].iter().all(|unit| is_digit(*unit))
            && query[digits_end..].iter().all(|unit| is_letter(*unit))
    };
    let split = if letters_then_digits {
        query.iter().position(|unit| is_digit(*unit))?
    } else if digits_then_letters {
        query.iter().position(|unit| !is_digit(*unit))?
    } else {
        return None;
    };
    let mut swapped = Vec::with_capacity(query.len());
    swapped.extend_from_slice(&query[split..]);
    swapped.extend_from_slice(&query[..split]);
    Some(swapped)
}

#[napi(js_name = "nativeFuzzyMatchLowerUtf16")]
pub fn native_fuzzy_match_lower_utf16(
    query_lower: Utf16String,
    text_lower: Utf16String,
) -> NativeFuzzyResult {
    let query_lower = query_lower.to_vec();
    let text_lower = text_lower.to_vec();
    let primary = fuzzy_match_query(&query_lower, &text_lower);
    if primary.matches {
        return primary;
    }
    let Some(swapped) = swapped_ascii_query(&query_lower) else {
        return primary;
    };
    let mut matched = fuzzy_match_query(&swapped, &text_lower);
    if matched.matches {
        matched.score += 5.0;
        matched
    } else {
        primary
    }
}

