fn raw_utf16_token_len(line: &str, index: usize, token_prefix: &str) -> Option<usize> {
    if token_prefix.is_empty() || !line[index..].starts_with(token_prefix) {
        return None;
    }
    let payload_start = index + token_prefix.len();
    let payload_end = payload_start.checked_add(32)?;
    let terminator = payload_end.checked_add(1)?;
    let bytes = line.as_bytes();
    if terminator > bytes.len()
        || !bytes[payload_start..payload_end]
            .iter()
            .all(|byte| matches!(byte, b'\x02' | b'\x03'))
        || bytes[payload_end] != b'\x04'
    {
        return None;
    }
    Some(terminator - index)
}

fn composite_grapheme_at<'a>(
    line: &'a str,
    index: usize,
    text_end: usize,
    token_prefix: &str,
) -> (&'a str, f64) {
    if let Some(token_len) = raw_utf16_token_len(line, index, token_prefix) {
        // A lone JavaScript surrogate has Grapheme_Cluster_Break=Other. Model it
        // with a temporary scalar only for segmentation so trailing marks/ZWJ
        // stay attached; keep the collision-free encoded token in the output.
        const PROBE: char = '\u{e000}';
        let suffix = &line[index + token_len..text_end];
        let mut probe = String::with_capacity(PROBE.len_utf8() + suffix.len());
        probe.push(PROBE);
        probe.push_str(suffix);
        let probe_len = probe.graphemes(true).next().map(str::len).unwrap_or(0);
        let suffix_len = probe_len.saturating_sub(PROBE.len_utf8());
        return (&line[index..index + token_len + suffix_len], 0.0);
    }

    let segment = line[index..text_end]
        .graphemes(true)
        .next()
        .expect("index is before text_end");
    (segment, grapheme_width(segment) as f64)
}

#[napi(js_name = "nativeCompositeVisibleWidth")]
pub fn native_composite_visible_width(line: String, token_prefix: String) -> f64 {
    let mut width = 0.0;
    let mut index = 0;
    while index < line.len() {
        if let Some(length) = extract_ansi_code_len(&line, index) {
            index += length;
            continue;
        }

        let mut text_end = index;
        while text_end < line.len() && extract_ansi_code_len(&line, text_end).is_none() {
            text_end += 1;
        }
        while index < text_end {
            let (segment, segment_width) =
                composite_grapheme_at(&line, index, text_end, &token_prefix);
            width += segment_width;
            index += segment.len();
        }
    }
    width
}

#[napi(js_name = "nativeExtractCompositeSegments")]
pub fn native_extract_composite_segments(
    line: String,
    before_end: f64,
    after_start: f64,
    after_len: f64,
    token_prefix: String,
) -> NativeCompositeSegments {
    // Keep JavaScript Number boundaries fractional: zero-width graphemes can be
    // observable even when no positive-width cell fits before a sub-unit edge.
    let after_end = after_start + after_len;
    let mut before = String::new();
    let mut before_width = 0.0;
    let mut after = String::new();
    let mut after_width = 0.0;
    let mut current_col = 0.0;
    let mut pending_ansi_before = String::new();
    let mut after_started = false;
    let mut style_tracker = AnsiCodeTracker::default();
    let mut index = 0;

    let done = |current_col: f64| {
        if after_len <= 0.0 {
            current_col >= before_end
        } else {
            current_col >= after_end
        }
    };

    'outer: while index < line.len() {
        if let Some(length) = extract_ansi_code_len(&line, index) {
            let code = &line[index..index + length];
            style_tracker.process(code);
            if current_col < before_end {
                pending_ansi_before.push_str(code);
            } else if current_col >= after_start && current_col < after_end && after_started {
                after.push_str(code);
            }
            index += length;
            continue;
        }

        let mut text_end = index;
        while text_end < line.len() && extract_ansi_code_len(&line, text_end).is_none() {
            text_end += 1;
        }
        while index < text_end {
            let (segment, width) = composite_grapheme_at(&line, index, text_end, &token_prefix);
            if current_col < before_end && current_col + width <= before_end {
                if !pending_ansi_before.is_empty() {
                    before.push_str(&pending_ansi_before);
                    pending_ansi_before.clear();
                }
                before.push_str(segment);
                before_width += width;
            } else if current_col >= after_start && current_col < after_end {
                let fits = current_col + width <= after_end;
                if fits {
                    if !after_started {
                        after.push_str(&style_tracker.get_active_codes());
                        after_started = true;
                    }
                    after.push_str(segment);
                    after_width += width;
                }
            }
            current_col += width;
            index += segment.len();
            if done(current_col) {
                break 'outer;
            }
        }
        index = text_end;
        if done(current_col) {
            break;
        }
    }

    NativeCompositeSegments {
        before,
        before_width,
        after,
        after_width,
    }
}

#[napi(js_name = "nativeSliceComposite")]
pub fn native_slice_composite(line: String, length: f64, token_prefix: String) -> String {
    if length <= 0.0 {
        return String::new();
    }

    let mut result = String::new();
    let mut current_col = 0.0;
    let mut index = 0;
    'outer: while index < line.len() {
        if let Some(code_length) = extract_ansi_code_len(&line, index) {
            if current_col >= 0.0 && current_col < length {
                result.push_str(&line[index..index + code_length]);
            }
            index += code_length;
            continue;
        }

        let mut text_end = index;
        while text_end < line.len() && extract_ansi_code_len(&line, text_end).is_none() {
            text_end += 1;
        }
        while index < text_end {
            let (segment, width) = composite_grapheme_at(&line, index, text_end, &token_prefix);
            let in_range = current_col >= 0.0 && current_col < length;
            let fits = current_col + width <= length;
            if in_range && fits {
                result.push_str(segment);
            }
            current_col += width;
            index += segment.len();
            if current_col >= length {
                break 'outer;
            }
        }
        index = text_end;
        if current_col >= length {
            break;
        }
    }
    result
}

