/// Canonical JavaScript's Kitty encoder chunks by UTF-16 code units, including
/// the possibility of splitting an astral pair. This adapter-only ABI keeps the
/// lower UTF-8 Rust codec intact while preserving the JavaScript boundary.
#[napi(js_name = "nativeEncodeKittyUtf16")]
pub fn native_encode_kitty_utf16(
    base64_data: Utf16String,
    options: Option<NativeKittyEncodeOptions>,
) -> Utf16String {
    let options = options.unwrap_or_default();
    let mut params = vec!["a=T".to_owned(), "f=100".to_owned(), "q=2".to_owned()];
    if options.move_cursor == Some(false) {
        params.push("C=1".to_owned());
    }
    if let Some(columns) = options.columns.filter(|value| *value != 0) {
        params.push(format!("c={columns}"));
    }
    if let Some(rows) = options.rows.filter(|value| *value != 0) {
        params.push(format!("r={rows}"));
    }
    if let Some(image_id) = options.image_id.filter(|value| *value != 0) {
        params.push(format!("i={image_id}"));
    }
    let params = params.join(",");
    let base64_data = base64_data.to_vec();
    let mut output = Vec::with_capacity(base64_data.len().saturating_add(96));

    if base64_data.len() <= KITTY_UTF16_CHUNK_SIZE {
        push_utf16(&mut output, &format!("\x1b_G{params};"));
        output.extend_from_slice(&base64_data);
        push_utf16(&mut output, "\x1b\\");
        return Utf16String::from(output);
    }

    for (index, chunk) in base64_data.chunks(KITTY_UTF16_CHUNK_SIZE).enumerate() {
        let is_first = index == 0;
        let is_last = (index + 1) * KITTY_UTF16_CHUNK_SIZE >= base64_data.len();
        if is_first {
            push_utf16(&mut output, &format!("\x1b_G{params},m=1;"));
        } else if is_last {
            push_utf16(&mut output, "\x1b_Gm=0;");
        } else {
            push_utf16(&mut output, "\x1b_Gm=1;");
        }
        output.extend_from_slice(chunk);
        push_utf16(&mut output, "\x1b\\");
    }
    Utf16String::from(output)
}

