/// Adapter-only iTerm2 encoder with a JavaScript-computed decoded byte length
/// and a raw UTF-16 payload. The private legacy entry point above deliberately
/// remains available to mutation tests for the lower Rust approximation.
#[napi(js_name = "nativeEncodeITerm2Utf16")]
pub fn native_encode_iterm2_utf16(
    base64_data: Utf16String,
    decoded_size: u32,
    options: Option<NativeITerm2EncodeOptions>,
) -> Utf16String {
    let options = options.unwrap_or_default();
    let mut params = vec![
        format!("inline={}", usize::from(options.inline != Some(false))),
        format!("size={decoded_size}"),
    ];
    if let Some(width) = options.width {
        params.push(format!("width={width}"));
    }
    if let Some(height) = options.height {
        params.push(format!("height={height}"));
    }
    if let Some(name) = options.name.as_deref().filter(|name| !name.is_empty()) {
        params.push(format!("name={}", base64_encode(name.as_bytes())));
    }
    if options.preserve_aspect_ratio == Some(false) {
        params.push("preserveAspectRatio=0".to_owned());
    }

    let base64_data = base64_data.to_vec();
    let mut output = Vec::with_capacity(base64_data.len().saturating_add(96));
    push_utf16(
        &mut output,
        &format!("\x1b]1337;File={}:", params.join(";")),
    );
    output.extend_from_slice(&base64_data);
    push_utf16(&mut output, "\x07");
    Utf16String::from(output)
}

fn base64_encode(bytes: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let first = chunk[0];
        let second = chunk.get(1).copied().unwrap_or(0);
        let third = chunk.get(2).copied().unwrap_or(0);
        output.push(ALPHABET[(first >> 2) as usize] as char);
        output.push(ALPHABET[(((first & 0x03) << 4) | (second >> 4)) as usize] as char);
        output.push(if chunk.len() > 1 {
            ALPHABET[(((second & 0x0f) << 2) | (third >> 6)) as usize] as char
        } else {
            '='
        });
        output.push(if chunk.len() > 2 {
            ALPHABET[(third & 0x3f) as usize] as char
        } else {
            '='
        });
    }
    output
}

